\begin{theorem}\label{Mainthm}
Suppose that $\mathcal{H}$ is a separable infinite dimensional Hilbert space. Let $\mathcal{P}$ be the collection of all probability measures on the closed unit ball $\{x \in \mathcal{H}: \left\lVert x \right\rVert \leq 1\}$. Given any $\mu \in \mathcal{P}$ and $n \geq 3$; let $\mu_n = \frac{1}{n}\summ{1}{n} \delta_{X_i}$ be the empirical distribution of $\mu$ from $n$ i.i.d samples $X_1, ..., X_n$ of $\mu$. Then,
\begin{equation*}
  \frac{c}{\sqrt{\log n}} \leq \sup_{\mu\in\mathcal{P}}(\mathbb{E}S_1^2(\mu, \mu_n))^{1/2} \leq \frac{C\sqrt{\log \log n}}{\sqrt{\log n}},  
\end{equation*}
where $c, C>0$ are universal constants.  
\end{theorem}

post_theorem_intro_text:
\begin{remark}
    The upper bound in Theorem \ref{Mainthm} also holds in the finite dimensional setting. Indeed, by Theorem \ref{Mainthm} and Proposition \ref{prop} below, we have \[\sup_{\mu\in\mathcal{P}_d}(\mathbb{E}S_1^2(\mu, \mu_n))^{1/2} \leq \frac{C\sqrt{\log \log n}}{\sqrt{\log n}},\] where $\mathcal{P}_d$ is the collection of all probability measures on $B_2^d = \{x \in \mathbb{R}^d: \|x\|_2\leq 1\}$.
\end{remark}

\begin{remark}
    By Remark \ref{rootk} and Theorem \ref{Mainthm}, we can also bound the $k$-dimensional subspace robust Wasserstein distance as follows: \[\sup_{\mu\in\mathcal{P}}(\mathbb{E}S_k^2(\mu, \mu_n))^{1/2} \leq \frac{C\sqrt{k \log \log n}}{\sqrt{\log n}}.\]
\end{remark}

\subsection{Some definitions and notations}\label{coupling}
Throughout this paper, the following will be used:\\
\begin{itemize}
    \item $\mathcal{H}$ denotes a \textbf{separable infinite dimensional  Hilbert space}. 
    \item Let $X$ be a random vector in $\mathcal{H}$. Then, $\mathbb{E}X$ is the vector in $\mathcal{H}$ such that \[\langle \mathbb{E}X, y \rangle = \mathbb{E}\langle X, y \rangle, \quad y \in \mathcal{H};\] and $\mathbb{E}(X \otimes X)$ is the positive semi-definite operator on $\mathcal{H}$ defined by 
\begin{equation*}
v \mapsto \mathbb{E}(\langle X , v \rangle X).
\end{equation*}For more details on random vectors in Hilbert spaces, refer to \cite{Hilbert}.
    \item $B_2^d \coloneq \{x \in \mathbb{R}^d: \|x\|_2\leq 1\}$ is the \textbf{closed unit ball in $\mathbb{R}^d$}, where $\|\cdot\|_2$ is the Euclidean norm on $\mathbb{R}^d$.
    \item If $A: \mathcal{H} \rightarrow \mathcal{H}$ is a bounded linear operator, then \[\left\lVert A \right\rVert_{\mathrm{op}} \coloneq  \sup_{\|x\| \leq 1} \|Ax\|. \] 
    \item If $(T, \rho)$ is a metric space and $\epsilon > 0$, then the \textbf{covering number} $N(T, \rho, \epsilon)$ is the smallest size possible among all subsets $S \subset T$ such that \[T \subset \underset{x \in S}{\cup}\{y \in T: \rho(x,y)\leq \epsilon\}.\] 
    \item If $(T, \rho)$ is a metric space and $\epsilon > 0$, then the \textbf{packing number} $N_{\mathrm{pack}}(T, \rho, \epsilon)$ is the largest size possible among all subsets $S \subset T$ such that \[ \rho(x,y)>\epsilon, \quad \forall \, x, y \in S,\; x \neq y.\] 
    \item If $E, F$ are sets, $\mu$ is a probability measure on $E$, and $Q:E \rightarrow F$, then $Q_{\#}\mu$ denotes the \textbf{pushforward probability measure} on $F$, i.e., \[Q_{\#}\mu(A) = \mu(Q^{-1}(A)),\] for all measurable $A \subset F$.
    \item If $\mu, \nu$ are two probability measures on a set $E$, then $\Pi(\mu, \nu)$ denotes the collection of all probability measures on $E \times E$ with marginal distributions $\mu$ and $\nu$ with respect to the first and second components respectively.
    \item For any probability measure $\mu$ on a set $E$, we will define $\mu_n = \frac{1}{n}\summ{1}{n}\delta_{X_i}$ to be the \textbf{empirical measure} of $\mu$, where $X_i$'s are independent samples of $\mu$ in $E$. 
\end{itemize}

\subsection{Organization of this paper}
In the rest of this paper, we prove Theorem \ref{Mainthm} after stating some results required for the proof.
\begin{itemize}
    \item In Section 2, we state some results that are useful for the rest of this paper.
    \item In Section 3, we prove the upper bound in Theorem \ref{Mainthm}. 
    \item In Section 4, we prove the lower bound in Theorem \ref{Mainthm}.
\end{itemize}

